model Customer { string Name; int Orders; }
void Main() {
 var a = new Customer { Name = "Ada", Orders = 2 }; var alias = a;
 var b = new Customer { Name = "Ada", Orders = 2 };
 Print(a == alias); Print(a == b); alias.Orders++;
 var copy = a with { Name = "Grace" };
 Print(copy == a); Print(a.Name + ":" + a.Orders); Print(copy.Name + ":" + copy.Orders);
 copy.Orders = 8; Print(a.Orders);
}
